#!/usr/bin/env node
'use strict';

/*
 * Company identity in meta tags, and the service-scope claims that were
 * corrected alongside it.
 *
 *   node scripts/check-identity-strings.js        (part of `npm test`)
 *
 * Two separate near-misses, both found on 2026-09-05, both with the same
 * shape: the shipped pages were correct (or were corrected) while the thing
 * that *writes* the pages was not.
 *
 *   1. og:site_name read "Triple Company Export Specialist" on every page
 *      generated by scripts/generate-resource-pages.py. The pages had been
 *      fixed by hand; the generator had not, so one re-run would have put the
 *      wrong company name back on roughly ten pages. This checks the shipped
 *      pages AND the generators.
 *
 *   2. "full design-to-shelf private label service" was live in 19 places
 *      across both locales, the two gated guides, both catalogue PDF sources
 *      and the same generator -- and had never been through the claim
 *      register at all. The owner's basis, given 2026-09-05, is that label
 *      design is offered *if the customer requests it*. That is a conditional
 *      offer, so the absolute is gone and this stops it coming back.
 *
 *   3. Operating Rule 1, re-confirmed 2026-09-06: "olivesegypt.com" is the
 *      website's domain and never the company's name. The sweep found zero
 *      violations -- no page, schema node, alt attribute, email template,
 *      form message or PDF used it as an identity -- so this rule guards a
 *      clean state rather than fixing a dirty one.
 *
 * The header taglines ("Premium Export Specialists", and the Arabic
 * equivalent) are deliberately NOT checked. They are descriptive subtitles
 * beneath the company name, they appear in no schema or meta field, and the
 * owner reviewed and kept them on 2026-09-05.
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = path.join(__dirname, '..');

const APPROVED_SITE_NAMES = new Set([
  'Triple Company for Industrial Development',
  'الشركة الثلاثية للتنمية الصناعية',
]);

/*
 * Phrases that assert a scope of service wider than anything the owner has
 * confirmed. Each was live and is now gone; the point of the list is that a
 * later edit reintroducing one fails the build rather than shipping.
 */
const BANNED = [
  { pattern: /design[-\s]to[-\s]shelf/i,
    why: 'claims an end-to-end private-label service; label design is offered on request, not as a full service' },
  { pattern: /من التصميم إلى الرف/,
    why: 'the Arabic form of the same claim' },
  { pattern: /full OEM and private label services/i,
    why: '"full" overstates a service whose artwork requirements are confirmed per project' },
  { pattern: /Full private-label ?\/ ?OEM service/i,
    why: 'same overstatement, shorter form' },
  { pattern: /Triple Company Export Specialist/i,
    why: 'not the company name; the approved name is "Triple Company for Industrial Development"' },

  /*
   * Operating Rule 1: olivesegypt.com is the website's domain, never the
   * company's name. Case-SENSITIVE on the capitalised forms on purpose --
   * the meta keywords legitimately carry lowercase phrases like "wholesale
   * olives Egypt" and "Manzanilla olives Egypt", which are search terms about
   * olives from Egypt, not a brand. A case-insensitive rule here would fail
   * on 19 pages for no reason.
   *
   * "olivesegypt.com" itself is untouched by this: it appears ~12 times per
   * catalogue PDF and throughout the site as a URL, an email domain, and in
   * phrases like "New inquiry received on olivesegypt.com" -- all correct
   * references to the website.
   */
  { pattern: /OlivesEgypt/,
    why: 'the domain written as a brand name; the company is "Triple Company for Industrial Development"' },
  { pattern: /Olives Egypt/,
    why: 'the domain written as a brand name; the company is "Triple Company for Industrial Development"' },

  /*
   * The partner processing facility is *approved* -- vetted and used by this
   * company. Whether it is *certified*, by whom, to what scope and until
   * when, is exactly what is still being verified against the certificate
   * documents. The two words are one keystroke apart in English and the same
   * word in Arabic (\u0645\u0639\u062a\u0645\u062f), so this is the phrase most likely to drift
   * back in.
   */
  { pattern: /certified partner facilit(y|ies)/i,
    why: 'no partner certificate has been verified yet; the approved wording is "approved partner facility"' },
];

const problems = [];
const tracked = execSync('git ls-files', { cwd: ROOT }).toString().trim().split('\n');
const pages = tracked.filter((f) => f.endsWith('.html'));
// The generators are the reason this file exists: a page fixed by hand is
// only fixed until the next regeneration.
//
// This file excludes itself. It has to name the banned strings in order to
// look for them, so scanning its own source finds every one of them and
// fails on the checker rather than on anything it is checking. That is not a
// hypothetical: the first version did exactly this and broke `npm test`.
const SELF = 'scripts/check-identity-strings.js';
const generators = tracked.filter(
  (f) => f !== SELF && (f.endsWith('.py') || (f.endsWith('.js') && f.startsWith('scripts/')))
);

// ---- og:site_name, on pages and in whatever writes them -----------------
for (const f of [...pages, ...generators]) {
  const src = fs.readFileSync(path.join(ROOT, f), 'utf8');
  for (const m of src.matchAll(/property="og:site_name" content="([^"]*)"/g)) {
    if (!APPROVED_SITE_NAMES.has(m[1])) {
      problems.push(`${f}: og:site_name is "${m[1]}", which is not an approved company name`);
    }
  }
}

// ---- service-scope claims ------------------------------------------------
for (const f of [...pages, ...generators]) {
  const src = fs.readFileSync(path.join(ROOT, f), 'utf8');
  for (const { pattern, why } of BANNED) {
    const hit = src.match(pattern);
    if (hit) problems.push(`${f}: "${hit[0]}" -- ${why}`);
  }
}

// ---- the built PDFs -----------------------------------------------------
//
// NOT checked here, deliberately. A PDF's text is Flate-compressed, so
// searching the file's bytes for a phrase finds nothing and reports OK
// whatever the document says -- a check that cannot fail is worse than no
// check, because it is mistaken for coverage. The first version of this file
// did exactly that.
//
// What is checked instead: the PDF *sources*, above, since both catalogues
// are generated from scripts/export-catalog-source*.html. When those change,
// regenerate and verify the artefacts by hand:
//
//   python3 -m http.server 8899 &
//   node scripts/generate-export-catalog-pdf.js
//   SOURCE_FILE=scripts/export-catalog-source-ar.html \
//   OUT_FILE=downloads/triple-company-export-catalog-2026-ar.pdf \
//   node scripts/generate-export-catalog-pdf.js

if (problems.length === 0) {
  console.log(
    `identity-strings OK -- ${pages.length} page(s) and ${generators.length} generator(s) carry only ` +
    `approved company names, and no unverified service-scope claim.`
  );
  process.exit(0);
}
console.error(`identity-strings FAILED -- ${problems.length} problem(s):\n`);
problems.forEach((p) => console.error('  ' + p));
process.exit(1);
